INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: File Terlalu Besar untuk Dikirim$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Email menolak lampiran di atas 25 MB, aplikasi chat membatasi ukuran file, dan mengunggah ratusan foto satu per satu memakan waktu lama. Masalahnya sering bukan jumlah file, melainkan ukurannya — dan solusinya adalah kompresi file.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Apa Itu Kompresi File$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Kompresi mengurangi ukuran file dengan menghilangkan redundansi data — pola berulang yang tidak perlu disimpan dua kali. Ada dua jenis: lossless yang tidak mengurangi kualitas (cocok untuk dokumen) dan lossy yang mengorbankan sedikit kualitas demi ukuran jauh lebih kecil (seperti foto JPEG). ZIP dan RAR adalah format arsip: mereka menggabungkan banyak file menjadi satu paket yang terkompresi.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Alat yang Dibutuhkan$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Komputer Windows, Mac, atau Linux — Windows 10/11 sudah punya fitur ZIP bawaan$txt$, $txt$Aplikasi 7-Zip (gratis, bisa membuka ZIP dan RAR) atau WinRAR$txt$, $txt$File-file yang ingin dikompresi$txt$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah: Membuat File ZIP$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Pilih file atau folder yang ingin dikompresi (tahan Ctrl lalu klik untuk memilih banyak file)$txt$, $txt$Klik kanan, lalu pilih Compress to ZIP file (Windows 11) atau Send to lalu Compressed folder (Windows 10)$txt$, $txt$Beri nama file ZIP, misalnya dokumen-kerja.zip$txt$, $txt$File ZIP siap dikirim — ukurannya bisa 10 sampai 90 persen lebih kecil tergantung jenis file$txt$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Langkah: Membuat dan Membuka File RAR$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Pasang WinRAR atau 7-Zip terlebih dahulu$txt$, $txt$Klik kanan file atau folder, pilih Add to archive, lalu pilih format RAR$txt$, $txt$Untuk membuka RAR: klik kanan, lalu pilih Extract Here atau Extract to folder$txt$, $txt$RAR umumnya mengompresi sedikit lebih baik dari ZIP, tetapi butuh aplikasi khusus untuk membukanya$txt$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Risiko dan Hal yang Perlu Diperhatikan$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$File yang sudah terkompresi (video MP4, foto JPG, dokumen PDF) tidak akan mengecil banyak jika di-ZIP ulang$txt$, $txt$Jangan membuka file ZIP atau RAR dari sumber yang tidak dikenal — bisa berisi virus$txt$, $txt$File RAR ber-password yang kata sandinya lupa praktis tidak bisa dibuka kembali$txt$, $txt$Pemeriksaan hasil: bandingkan ukuran sebelum dan sesudah. Jika tidak mengecil signifikan, kirim saja file aslinya$txt$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Kaki Tiba-tiba Kram$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Kram kaki — otot betis atau telapak kaki yang mengencang tiba-tiba dan terasa nyeri — sering menyerang di malam hari atau saat berolahraga. Rasanya seperti otot terkunci dan bisa berlangsung beberapa detik hingga beberapa menit.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Mengapa Otot Bisa Kram$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Kram terjadi ketika otot berkontraksi tanpa disadari dan tidak bisa rileks kembali. Penyebab umumnya antara lain dehidrasi, kekurangan elektrolit seperti kalium dan magnesium, otot yang kelelahan setelah aktivitas berat, duduk atau berdiri terlalu lama dalam satu posisi, serta sirkulasi darah yang kurang lancar. Pada lansia, kram pada malam hari lebih sering terjadi.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Persiapan: Yang Perlu Disiapkan$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Air putih untuk menjaga hidrasi$txt$, $txt$Handuk hangat atau botol berisi air hangat$txt$, $txt$Catatan pola kram: kapan terjadi, berapa lama, dan seberapa sering$txt$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah: Mengatasi Kram Saat Terjadi$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Hentikan aktivitas, lalu duduk atau berbaring dengan nyaman$txt$, $txt$Regangkan otot yang kram secara perlahan — untuk betis, tarik ujung kaki ke arah tubuh$txt$, $txt$Pijat area yang kram dengan lembut selama satu sampai dua menit$txt$, $txt$Tempelkan kompres hangat untuk merilekskan otot, atau kompres dingin bila masih nyeri setelahnya$txt$, $txt$Minum air putih setelah kram mereda$txt$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Langkah: Mencegah Kram Kambuh$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Minum cukup air setiap hari, terutama sebelum, saat, dan sesudah berolahraga$txt$, $txt$Lakukan pemanasan sebelum olahraga dan pendinginan setelahnya$txt$, $txt$Regangkan otot betis secara rutin setiap pagi dan sebelum tidur$txt$, $txt$Hindari duduk atau berdiri dalam satu posisi terlalu lama$txt$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Kapan Harus ke Dokter$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Segera konsultasikan ke dokter bila kram sangat sering terjadi, terasa sangat nyeri, disertai bengkak atau kemerahan, melemahkan otot, atau tidak membaik setelah beberapa minggu. Artikel ini hanya informasi umum dan bukan pengganti nasihat medis profesional.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Siapa Suku Osing?$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Suku Osing adalah masyarakat asli Banyuwangi, Jawa Timur, yang bahasanya merupakan campuran Jawa kuno dan Bali. Mereka dikenal sebagai penjaga tradisi Blambangan — kerajaan Hindu terakhir di Jawa — dan masih memegang teguh ritual adat hingga kini.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Kebo-keboan: Ritual Syukur Panen$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Kebo-keboan adalah ritual adat Osing untuk mensyukuri panen dan memohon kesuburan tanah. Para peserta berdandan menyerupai kerbau — tubuh dilumuri lumpur, memakai tanduk, lalu berkeliling desa diiringi musik gamelan. Ritual ini melambangkan kerbau sebagai sahabat setia para petani.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Makna di Balik Ritual$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Lebih dari sekadar tontonan, kebo-keboan adalah doa kolektif. Lumpur melambangkan kesuburan tanah, arak-arakan melambangkan gotong royong, dan seluruh warga desa terlibat — tua dan muda, laki-laki dan perempuan. Ritual ini biasanya digelar setelah panen raya.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Tradisi Osing Lainnya$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Selain kebo-keboan, suku Osing memiliki tradisi Seblang — tarian sakral penolak bala — serta Barong Ider Bumi dan upacara perkawinan adat yang khas. Bahasa Osing sendiri terus dilestarikan melalui sekolah dan festival budaya.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Pelajaran dari Suku Osing$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Suku Osing menunjukkan bahwa modernisasi tidak harus menghapus tradisi. Dengan menjadikan ritual sebagai festival budaya yang terbuka untuk umum, mereka justru memperkuat identitas sekaligus menggerakkan ekonomi wisata Banyuwangi — warisan yang hidup, bukan sekadar pajangan museum.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Apa Itu Suhu?$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Suhu adalah ukuran derajat panas atau dinginnya suatu benda. Secara fisika, suhu mencerminkan energi kinetik rata-rata partikel penyusun benda — semakin cepat partikel bergerak, semakin tinggi suhunya. Suhu diukur dengan termometer dalam satuan Celsius, Fahrenheit, atau Kelvin.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Apa Itu Kalor?$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Kalor adalah energi yang berpindah dari benda bersuhu tinggi ke benda bersuhu rendah. Suhu menggambarkan seberapa panas suatu benda, sedangkan kalor menggambarkan berapa banyak energi panas yang berpindah. Satuan kalor adalah joule — bukan derajat.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Tiga Cara Perpindahan Kalor$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Kalor berpindah melalui tiga cara. Konduksi adalah perpindahan lewat sentuhan langsung, seperti sendok logam yang ikut panas saat mengaduk teh. Konveksi terjadi lewat aliran fluida, seperti air mendidih yang berputar-putar. Radiasi berpindah lewat gelombang elektromagnetik, seperti panas matahari yang sampai ke Bumi tanpa perantara apa pun.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Hukum Kekekalan Energi$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Hukum pertama termodinamika menyatakan bahwa energi tidak dapat diciptakan maupun dimusnahkan — ia hanya berubah bentuk. Kalor yang hilang dari satu benda pasti diterima oleh benda lain. Inilah prinsip dasar semua mesin panas, dari mesin uap kuno hingga pembangkit listrik modern.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Suhu dan Kalor dalam Kehidupan Sehari-hari$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Prinsip suhu dan kalor bekerja di mana-mana. Termos menahan konduksi dan konveksi agar minuman tetap panas, AC memindahkan kalor dari dalam ruangan ke luar, jaket tebal menahan kalor tubuh agar tidak lepas, dan panel surya menangkap radiasi matahari. Memahami keduanya berarti memahami separuh cara dunia bekerja.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah mempelajari materi ini, kamu diharapkan mampu mengenal unsur-unsur bentuk aljabar (variabel, koefisien, konstanta, dan suku), melakukan operasi penjumlahan dan pengurangan bentuk aljabar, serta menyelesaikan soal cerita sederhana.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Apa Itu Bentuk Aljabar?$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Bentuk aljabar adalah kalimat matematika yang memuat huruf sebagai pengganti bilangan. Contohnya 3x + 5. Huruf x disebut variabel karena nilainya bisa berubah, angka 3 disebut koefisien karena mengalikan variabel, dan angka 5 disebut konstanta karena nilainya tetap.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Unsur-unsur Bentuk Aljabar$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Variabel: huruf pengganti bilangan, misalnya x, y, atau a$txt$, $txt$Koefisien: angka di depan variabel, misalnya 3 pada 3x$txt$, $txt$Konstanta: angka tanpa variabel, misalnya 5 pada 3x + 5$txt$, $txt$Suku: bagian yang dipisahkan tanda tambah atau kurang, misalnya 3x dan 5 adalah dua suku$txt$, $txt$Suku sejenis: suku dengan variabel yang sama, misalnya 3x dan 7x$txt$])));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Penjumlahan dan Pengurangan Bentuk Aljabar$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Hanya suku sejenis yang bisa dijumlahkan atau dikurangkan — jumlahkan koefisiennya, variabelnya tetap. Contoh: 3x + 7x = 10x, dan 5y kurang 2y = 3y. Ingat: 3x + 5y tidak bisa digabung karena variabelnya berbeda.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Contoh Soal Terpecahkan$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Contoh 1: sederhanakan 4a + 3b kurang 2a + 5b. Jawab: kumpulkan suku sejenis menjadi (4a kurang 2a) + (3b + 5b) = 2a + 8b. Contoh 2: sederhanakan 6x kuadrat + 2x kurang 3x kuadrat + 4. Jawab: (6x kuadrat kurang 3x kuadrat) + 2x + 4 = 3x kuadrat + 2x + 4.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan Soal$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Sederhanakan: 5p + 2q kurang 3p + 4q$txt$, $txt$Sederhanakan: 7x kurang 4 + 2x + 9$txt$, $txt$Tentukan koefisien, variabel, dan konstanta dari 8y kurang 3$txt$, $txt$Kunci jawaban: (1) 2p + 6q, (2) 9x + 5, (3) koefisien 8, variabel y, konstanta kurang 3$txt$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah mempelajari materi ini, kamu diharapkan mampu mengenal pecahan senilai, membandingkan dua pecahan, serta melakukan penjumlahan dan pengurangan pecahan berpenyebut sama.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Apa Itu Pecahan?$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Pecahan adalah bagian dari keseluruhan. Ditulis a per b, dengan a disebut pembilang (bagian yang diambil) dan b disebut penyebut (jumlah bagian yang sama besar). Contoh: satu per dua artinya satu dari dua bagian sama besar — seperti setengah potong kue.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Pecahan Senilai$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Pecahan senilai adalah pecahan yang nilainya sama meski penulisannya berbeda, misalnya satu per dua sama dengan dua per empat sama dengan tiga per enam. Caranya: kalikan atau bagi pembilang dan penyebut dengan bilangan yang sama. Contoh: satu per dua dikali dua per dua sama dengan dua per empat.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Membandingkan Pecahan$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Jika penyebutnya sama, pecahan dengan pembilang lebih besar nilainya lebih besar: tiga per lima lebih besar dari dua per lima. Jika penyebutnya berbeda, samakan dulu penyebutnya. Contoh: satu per dua dan satu per tiga disamakan menjadi tiga per enam dan dua per enam, jadi satu per dua lebih besar dari satu per tiga.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Penjumlahan dan Pengurangan Pecahan$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Untuk penyebut yang sama, jumlahkan atau kurangkan pembilangnya saja: dua per tujuh tambah tiga per tujuh sama dengan lima per tujuh; lima per enam kurang dua per enam sama dengan tiga per enam yang disederhanakan menjadi satu per dua. Untuk penyebut berbeda, samakan penyebutnya dulu menggunakan KPK.$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan Soal$txt$));
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Tuliskan pecahan senilai dari dua per tiga dengan mengalikan pembilang dan penyebut dengan 2$txt$, $txt$Bandingkan: tiga per empat ... lima per delapan (isi dengan lebih besar atau lebih kecil)$txt$, $txt$Hitung: satu per lima tambah tiga per lima$txt$, $txt$Kunci jawaban: (1) empat per enam, (2) tiga per empat lebih besar dari lima per delapan, (3) empat per lima$txt$])));
